// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public Node insert(Node root, int v) {
    if (root == null) return new Node(v);   // empty slot found → create
    if (v < root.data) {
        root.left = insert(root.left, v);   // reassign the left link
    } else {
        root.right = insert(root.right, v); // reassign the right link
    }
    return root;                            // hand this subtree back up
}

