# Definition for a binary tree node.
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def insert(root: Node, v: int) -> Node:
    if root is None:                        # empty slot found -> create
        return Node(v)
    if v < root.data:
        root.left = insert(root.left, v)    # reassign the left link
    else:
        root.right = insert(root.right, v)  # reassign the right link
    return root                             # hand this subtree back up

