public Node insert(Node root, int v) {
    Node node = new Node(v);
    if (root == null) return node;          // empty tree → new node is root
    Node parent = null;
    Node cur = root;
    boolean goLeft = false;
    while (cur != null) {                    // descend to a null slot
        parent = cur;
        if (v < cur.data) {
            cur = cur.left;
            goLeft = true;
        } else {
            cur = cur.right;
            goLeft = false;
        }
    }
    if (goLeft) parent.left = node;          // attach on the recorded side
    else parent.right = node;
    return root;
}

